/**
 * The Settings window as a docs scene: the app's SettingsHub
 * (src/panels/SettingsHub.tsx) open over the app window, with its nav
 * (sections, and the open section's pages) and the page a doc is about in
 * its content area. Styled by the app's own stylesheet (components/home/app.css).
 *
 * The hub is a `.modal-backdrop` (position: fixed) the app portals to the
 * document body; here it sits inside the scene window, whose backdrop filter
 * makes it the containing block, so the backdrop covers the window and the
 * dialog centres in it as it does in the app.
 */
import { useId, useLayoutEffect, useRef, type CSSProperties, type ReactNode } from "react";
import { Bell, Blocks, ChevronDown, CircleQuestionMark, FolderSync, HardDrive, Info, MessageSquare, Settings, ShieldCheck, X } from "lucide-react";
import { Shot } from "../../home/Chrome";
import type { BackdropScene } from "../../home/Backdrop";
import { AppWindow, SessionTile, WIN_SIZE } from "../../home/Scenes";
import { ActiveCanvas } from "../../home/Interactive";
import { betweenLines, columnGap, columnWidth, SPACE } from "../workspace/grid";

/** SettingsHub's sections, in its order, with their icons. */
const SECTIONS = [
  { id: "general", label: "General", icon: Settings },
  { id: "notifications", label: "Notifications", icon: Bell },
  { id: "quick-chat", label: "Quick Chat", icon: MessageSquare },
  { id: "devices", label: "Devices", icon: HardDrive },
  { id: "sync", label: "Sync", icon: FolderSync },
  { id: "mcp", label: "Connections", icon: Blocks },
  { id: "security", label: "Security", icon: ShieldCheck },
  { id: "help", label: "Help", icon: CircleQuestionMark },
  { id: "about", label: "About", icon: Info },
] as const;

export type SettingsSectionId = (typeof SECTIONS)[number]["id"];

interface SubPage {
  id: string;
  label: string;
}

/* Each section's pages as the macOS app lists them (src/panels/settingsSections.ts
   and SettingsHub): Dictation and Power exist on macOS, the permission and
   default editor pages where macOS permissions do, and Remote desktop once a
   remote device is added (the demo has Devbox). */
const SUBPAGES: Partial<Record<SettingsSectionId, { label: string; items: readonly SubPage[] }>> = {
  general: {
    label: "General settings",
    items: [
      { id: "appearance", label: "Appearance" },
      { id: "bars", label: "Menu buttons" },
      { id: "terminal", label: "Terminal" },
      { id: "prompts", label: "Saved prompts" },
      { id: "dictation", label: "Dictation" },
      { id: "power", label: "Power" },
    ],
  },
  notifications: {
    label: "Notification pages",
    items: [
      { id: "activity", label: "Activity" },
      { id: "preferences", label: "Preferences" },
    ],
  },
  sync: {
    label: "Sync pages",
    items: [
      { id: "repositories", label: "Repositories" },
      { id: "preferences", label: "Preferences" },
    ],
  },
  mcp: {
    label: "Connection settings",
    items: [
      { id: "mcp", label: "MCP integrations" },
      { id: "remote", label: "Remote desktop" },
      { id: "ports", label: "Port forwarding" },
    ],
  },
  security: {
    label: "Security pages",
    items: [
      { id: "tools", label: "Tools" },
      { id: "permissions", label: "Permissions" },
      { id: "tmux", label: "tmux permissions" },
      { id: "editor", label: "Default editor" },
      { id: "device", label: "This device" },
    ],
  },
};

/** Sections whose nav entry folds out into pages (Help's are its topic tree). */
const HAS_CHILDREN: readonly SettingsSectionId[] = ["general", "security", "notifications", "sync", "mcp", "help"];

/** A card the Settings scenes' size, centred on the window (the setup screen's card). */
export const SETTINGS_FRAME = { width: 860, height: 580 };

/* The grid behind the dialog, framed so no card edge cuts through it. The
   dialog (720 x 500) sits at 360, 200 in the window, so a card with some
   room around it has its sides near x 290 and 1150: in a five-column grid
   those are the gaps after the first column and before the last. Fieldnotes'
   three sessions share the row, api spanning the middle three columns (the
   app's saved spans) between web and docs, which the card leaves out. The
   card's top and bottom fall between api's terminal rows. */
const COLUMN = columnWidth(5);

/** The part of the window a Settings card shows (window pixels): the dialog with the dimmed grid around it. */
export const SETTINGS_VIEW = {
  left: columnGap(5, 1),
  right: columnGap(5, 4),
  top: betweenLines(1, 0, 5),
  bottom: betweenLines(1, 0, 43),
};

/** The window placed in a Settings card. */
export const SETTINGS_WINDOW_BOX = { left: -SETTINGS_VIEW.left, top: -SETTINGS_VIEW.top, ...WIN_SIZE };

/** Fieldnotes' sessions in the grid the Settings cards frame (see SETTINGS_VIEW). */
export function SettingsCanvas() {
  // web and docs are outside every Settings card; they show the narrower captures.
  return (
    <ActiveCanvas
      initial={1}
      style={{ gridTemplateColumns: `${COLUMN}fr ${COLUMN * 3 + SPACE * 2}fr ${COLUMN}fr` }}
      tiles={[
        <SessionTile key="web" id="web" capture="web-57" kbd="⌘1" />,
        <SessionTile key="api" id="api" capture="api-86" kbd="⌘2" />,
        <SessionTile key="docs" id="docs" capture="docs-57" kbd="⌘3" />,
      ]}
    />
  );
}

/* The app sizes the dialog in viewport units (min(500px, 82vh)); the
   stylesheet reads them from --pz-vh / --pz-vw, set here to the scene
   window's 1440 x 900 so the dialog keeps its size whatever the browser's. */
const WINDOW_VIEWPORT = { "--pz-vh": `${WIN_SIZE.height / 100}px`, "--pz-vw": `${WIN_SIZE.width / 100}px` } as CSSProperties;

/** .settings-hub-content's padding, which a scrolled page keeps above its target. */
const CONTENT_PADDING = 22;

/** Elements that are read or pressed: a scroll edge may pass beside them, never through them. */
const SOLID = "button, input, summary, svg, kbd, code, .switch";
/** Rounding slack, in scene pixels, before an edge counts as cutting an element. */
const SLACK = 0.5;

interface Span {
  top: number;
  bottom: number;
}

/** `el`'s place in `box`'s scroll coordinates, in scene pixels (the Stage may scale the scene). */
function spanOf(el: Element, box: HTMLElement, scale: number): Span {
  const origin = box.getBoundingClientRect().top;
  const rect = el.getBoundingClientRect();
  return { top: (rect.top - origin) / scale + box.scrollTop, bottom: (rect.bottom - origin) / scale + box.scrollTop };
}

/** Every line of text and every control inside `box`. */
function solidSpans(box: HTMLElement, scale: number): Span[] {
  const spans: Span[] = [];
  for (const el of box.querySelectorAll("*")) {
    const text = [...el.childNodes].some((node) => node.nodeType === Node.TEXT_NODE && node.textContent?.trim());
    if ((text || el.matches(SOLID)) && el.getBoundingClientRect().height) spans.push(spanOf(el, box, scale));
  }
  return spans;
}

/**
 * The scroll position nearest `preferred` at which neither edge of `box`
 * cuts through a line of text or a control, with `keep` (the open page's
 * entry) in view: where a visitor would leave a list or page they scrolled.
 * Falls back to `preferred` when there is none.
 */
function cleanScroll(box: HTMLElement, preferred: number, keep?: Element | null): number {
  const scale = box.getBoundingClientRect().height / box.offsetHeight || 1;
  const height = box.clientHeight;
  const max = Math.max(0, Math.floor(box.scrollHeight - height));
  const spans = solidSpans(box, scale);
  const kept = keep ? spanOf(keep, box, scale) : null;
  const inside = ({ top, bottom }: Span, at: number) => top >= at - SLACK && bottom <= at + height + SLACK;
  const clean = (at: number) =>
    spans.every((span) => span.bottom <= at + SLACK || span.top >= at + height - SLACK || inside(span, at)) && (!kept || inside(kept, at));
  const start = Math.min(max, Math.max(0, Math.round(preferred)));
  for (let distance = 0; distance <= max; distance += 1) {
    for (const at of [start + distance, start - distance]) if (at >= 0 && at <= max && clean(at)) return at;
  }
  return start;
}

/** SettingsHub's SettingsSubnav: the open section's pages. */
function SettingsSubnav({ label, items, value }: { label: string; items: readonly SubPage[]; value?: string }) {
  return (
    <div className="settings-nav-children" role="group" aria-label={label}>
      {items.map(({ id, label: itemLabel }) => (
        <button type="button" key={id} aria-current={value === id ? "page" : undefined} className={`settings-hub-sublink ${value === id ? "active" : ""}`}>
          <span className="settings-hub-sublabel">{itemLabel}</span>
        </button>
      ))}
    </div>
  );
}

/** The Settings dialog itself, `section` open on `page`, showing `children`. */
export function SettingsHubDialog({
  section,
  page,
  helpNav,
  scrollTo,
  folded = false,
  children,
}: {
  section: SettingsSectionId;
  /** The open page of a section with pages. */
  page?: string;
  /** Help's topic tree (the app's HelpNav), shown under Help when it is open. */
  helpNav?: ReactNode;
  /** A selector in the page to show scrolled to the top of the content, for a page taller than the dialog. */
  scrollTo?: string;
  /** The open section's pages folded away (its entry clicked again), for a nav too tall to show them whole. */
  folded?: boolean;
  children: ReactNode;
}) {
  const titleId = useId();
  const nav = useRef<HTMLElement>(null);
  const content = useRef<HTMLDivElement>(null);
  // The nav and the page scroll in the app when they are taller than the
  // dialog. Each is shown where a visitor would leave it: the page at
  // `scrollTo` (or its top), the nav from its top with the open page in view,
  // and neither edge cutting through a line or a control.
  useLayoutEffect(() => {
    const list = nav.current;
    if (list) list.scrollTop = cleanScroll(list, 0, list.querySelector('[aria-current="page"]'));
    const box = content.current;
    if (!box) return;
    const target = scrollTo ? box.querySelector(scrollTo) : null;
    const preferred = target ? spanOf(target, box, box.getBoundingClientRect().height / box.offsetHeight || 1).top - CONTENT_PADDING : 0;
    box.scrollTop = cleanScroll(box, preferred);
  }, [scrollTo, section, page]);
  return (
    <div className="modal-backdrop pzza-portal settings-hub-backdrop" style={WINDOW_VIEWPORT}>
      <div className="modal settings-hub" role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1}>
        <div className="modal-head">
          <span className="modal-title" id={titleId}>
            <Settings size={16} /> Settings
          </span>
          <button type="button" className="dismiss-btn" aria-label="Close Settings">
            <X size={16} />
          </button>
        </div>
        <div className="settings-hub-layout">
          <nav ref={nav} className="settings-hub-nav" aria-label="Settings sections">
            {SECTIONS.map(({ id, label, icon: Icon }) => {
              const active = section === id;
              const hasChildren = HAS_CHILDREN.includes(id);
              const expanded = active && !folded;
              const subpages = SUBPAGES[id];
              return (
                <div className="settings-nav-group" key={id}>
                  <button
                    type="button"
                    aria-current={active && !hasChildren ? "page" : undefined}
                    aria-expanded={hasChildren ? expanded : undefined}
                    className={`settings-hub-link ${active ? "active" : ""}`}
                  >
                    <Icon size={16} />
                    <span>{label}</span>
                    {hasChildren ? <ChevronDown size={13} className="settings-nav-chevron" /> : null}
                  </button>
                  {expanded && subpages ? <SettingsSubnav label={subpages.label} items={subpages.items} value={page} /> : null}
                  {expanded && id === "help" ? helpNav : null}
                </div>
              );
            })}
          </nav>
          <div className="settings-hub-main">
            {/* Help has a column of its own (SettingsHub): the settings pages'
                column stays, hidden, and Help's page shows beside it. */}
            <div ref={section === "help" ? undefined : content} className="settings-hub-content" hidden={section === "help"}>
              {section === "help" ? null : children}
            </div>
            {section === "help" ? (
              <div ref={content} className="help-hub-content">
                {children}
              </div>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Settings open over the app window, framed on the dialog. The grid behind it
 * is Fieldnotes' three sessions (SettingsCanvas).
 */
export function SettingsWindow({
  section,
  page,
  helpNav,
  scrollTo,
  folded,
  backdrop = "spaces",
  children,
}: {
  section: SettingsSectionId;
  page?: string;
  helpNav?: ReactNode;
  scrollTo?: string;
  folded?: boolean;
  backdrop?: BackdropScene;
  children: ReactNode;
}) {
  return (
    <Shot id={backdrop} width={SETTINGS_VIEW.right - SETTINGS_VIEW.left} height={SETTINGS_VIEW.bottom - SETTINGS_VIEW.top}>
      <AppWindow box={SETTINGS_WINDOW_BOX}>
        <SettingsCanvas />
        <SettingsHubDialog section={section} page={page} helpNav={helpNav} scrollTo={scrollTo} folded={folded}>
          {children}
        </SettingsHubDialog>
      </AppWindow>
    </Shot>
  );
}
